import json, html, pathlib, datetime
P=pathlib.Path(__file__).parent
D=json.loads((P/'knowledge.json').read_text()); E=D['entries']; S=D['sources']; M={e['id']:e for e in E}
esc=html.escape
questions=[('容量','K01'),('停工','K02'),('使用執照','K03'),('亞洲棒球錦標賽','K04'),('東京巨蛋','K05'),('演唱會','K06'),('捷運','K07'),('公共安全','K08')]
def search(q, improved):
    return [e['id'] for e in E if q.lower() in (e['title'] if not improved else ' '.join([e['title'],e['question'],*e['tags'],e['text']])).lower()]
rounds=[]
for improved in [False,True]:
    rows=[dict(query=q,expected=k,found=search(q,improved),passed=k in search(q,improved)) for q,k in questions]
    rounds.append(dict(mode='title+question+tags+text' if improved else 'title',passed=sum(r['passed'] for r in rows),total=len(rows),rows=rows))
checks={'source_count':len(S),'entry_count':len(E),'all_entries_have_valid_sources':all(e['refs'] and set(e['refs'])<=set(s[0] for s in S) for e in E),'distinct_opening_dates':all(x in M['K03']['text'] for x in ['11月2日','11月18日','12月2日','12月3日']),'championship_location_disambiguated':'日本東京巨蛋' in M['K05']['text'] and '不是在臺北大巨蛋' in M['K05']['text']}
assert all(v for k,v in checks.items() if isinstance(v,bool)) and rounds[1]['passed']==len(E)
log=dict(executed=datetime.datetime.now(datetime.timezone.utc).isoformat(),rounds=rounds,checks=checks,limitations='自訂關鍵詞命中測試；不是語意檢索、獨立評估集或自動事實查證。來源由LLM閱讀整理，日期與地點經人工式對照。')
(P/'run_log.json').write_text(json.dumps(log,ensure_ascii=False,indent=2))
CSS='''*{box-sizing:border-box}html{color-scheme:dark}body{margin:0;background:#101b25;color:#f5f4eb;font:17px/1.65 system-ui,"Noto Sans TC",sans-serif}a{color:#86edd5}header,main,footer{max-width:1080px;margin:auto;padding:24px}header{display:flex;gap:20px;align-items:center;justify-content:space-between;flex-wrap:wrap}nav{display:flex;gap:16px;flex-wrap:wrap}h1,h2,h3,p{margin:0 0 16px}h1{font-size:clamp(34px,5vw,66px);line-height:1.14;letter-spacing:-.04em}h2{font-size:clamp(26px,3.4vw,46px);line-height:1.23;letter-spacing:-.025em}h3{font-size:22px}.kicker{color:#86edd5;font-weight:800;letter-spacing:.15em;font-size:14px}.muted,small{color:#becbd0}.panel{padding:24px;border:1px solid #3d5660;background:#172a35;border-radius:18px;margin:16px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px}.big{font-size:clamp(48px,8vw,100px);font-weight:900;color:#e7fc9b;line-height:1.1}.tag{display:inline-block;font-size:13px;background:#263d48;border-radius:20px;padding:3px 10px;margin:4px}button,input{font:inherit;border-radius:9px;padding:10px 16px;border:1px solid #607c82;background:#233e49;color:#fff}button{cursor:pointer}button:hover{background:#345965}button:disabled{opacity:.4;cursor:default}input{width:100%;margin:12px 0}table{border-collapse:collapse;width:100%}td,th{padding:10px;text-align:left;border-bottom:1px solid #425965}svg{display:block;width:100%;height:auto}.slide{display:none;min-height:65vh;padding:clamp(16px,4vw,48px);border:1px solid #3d5660;background:linear-gradient(130deg,#1a3440,#14232e);border-radius:24px}.slide.active{display:block}.slide p{font-size:clamp(17px,2vw,24px)}.slide .kicker{margin-bottom:18px}.slide small{font-size:14px} .controls{display:flex;gap:10px;align-items:center;justify-content:space-between;flex-wrap:wrap;margin-top:16px}progress{width:100%;accent-color:#a9ead0;height:8px}.quiz{display:flex;gap:12px;flex-wrap:wrap}.quiz button{flex:1}.timeline{border-left:3px solid #86edd5;padding-left:20px}.timeline b{color:#e7fc9b}pre{white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:600px){header,main,footer{padding:16px}.slide{min-height:70vh}.grid{grid-template-columns:1fr}td,th{font-size:14px;padding:7px}}@media print{.slide{display:block;break-after:page;min-height:0;background:white;color:black}body{background:white;color:black}.controls,header,progress{display:none}}'''
def page(title,body,js=''):
    return f'<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>{CSS}</style><body><header><strong>TAIPEI DOME / 知識專題</strong><nav><a href="report.html">作業報告</a><a href="wiki.html">LLM Wiki</a><a href="slides.html">教學簡報</a></nav></header><main>{body}</main><footer><small>臺北大巨蛋知識專題 · 2023–2024 歷史案例 · 2026-11-18 整理</small></footer><script>{js}</script></body></html>'
def links(refs):return ' '.join(f'<a href="wiki.html#{s}">{s}</a>' for s in refs)
def srclist():return ''.join(f'<article class="panel" id="{s[0]}"><h3>{s[0]} · <a href="{esc(s[3],quote=True)}" target="_blank" rel="noopener">{esc(s[1])}</a></h3><small>{esc(s[2])}</small><p>{esc(s[4])}</p></article>' for s in S)
wiki='<p class="kicker">KNOWLEDGE BASE / 10 SOURCES</p><h1>臺北大巨蛋 Wiki</h1><p>8 個知識條目，10 篇來源摘要。輸入關鍵詞如「東京巨蛋」或「公共安全」查詢。</p><input id="search" placeholder="搜尋知識條目…" aria-label="搜尋知識條目"><p id="count">8 筆知識</p>'
for e in E:
    wiki+=f'<article class="panel entry" id="{e["id"]}" data-search="{esc(" ".join([e["title"],e["question"],*e["tags"],e["text"]]),quote=True)}"><p class="kicker">{e["id"]}</p><h3>{e["title"]}</h3><p><b>{e["question"]}</b></p><p>{e["text"]}</p><div>'+''.join(f'<span class="tag">{t}</span>' for t in e['tags'])+'</div><p>來源：'+' '.join(f'<a href="#{s}">{s}</a>' for s in e['refs'])+'</p></article>'
wiki+='<h2>來源資料庫</h2>'+srclist()
(P/'wiki.html').write_text(page('臺北大巨蛋 Wiki',wiki,"const q=document.querySelector('#search');q.oninput=()=>{let n=0;document.querySelectorAll('.entry').forEach(e=>{e.hidden=!e.dataset.search.toLowerCase().includes(q.value.trim().toLowerCase());n+=!e.hidden});document.querySelector('#count').textContent=n+' 筆知識';};"))
md='# 臺北大巨蛋 LLM Wiki\n\n'
for e in E:md+=f'## {e["id"]} {e["title"]}\n\n{e["question"]}\n\n{e["text"]}\n\n標籤：{", ".join(e["tags"])}\n\n來源：{", ".join(e["refs"])}\n\n'
md+='## 來源\n\n'+''.join(f'- {s[0]} [{s[1]}]({s[3]})（{s[2]}）：{s[4]}\n' for s in S)
(P/'wiki.md').write_text(md)
# Teaching content is assembled from retrieved entries, not independently generated facts.
field='''<svg viewBox="0 0 600 310" role="img" aria-label="室內棒球場概念示意圖"><defs><pattern id="stripe" width="22" height="22" patternUnits="userSpaceOnUse"><rect width="22" height="22" fill="#367950"/><rect width="11" height="22" fill="#44865b"/></pattern></defs><ellipse cx="300" cy="155" rx="280" ry="137" fill="#617781"/><ellipse cx="300" cy="155" rx="251" ry="115" fill="#172b36"/><ellipse cx="300" cy="155" rx="230" ry="97" fill="url(#stripe)"/><path d="M300 250L143 115Q300 18 457 115Z" fill="#529967"/><path d="M300 226L235 160L300 95L365 160Z" fill="#bd835d"/><path d="M300 207L254 160L300 114L346 160Z" fill="#438658"/><circle cx="300" cy="160" r="10" fill="#bd835d"/><path d="M300 226L143 115M300 226L457 115" stroke="#f8f5dc" stroke-width="2"/><path d="M300 225l7 -4v-7h-14v7z" fill="white"/><path d="M20 140Q300 -55 580 140" stroke="#b1d9d7" stroke-width="5" fill="none" stroke-dasharray="9 5"/><text x="300" y="297" fill="#e7fc9b" font-size="15" text-anchor="middle">室內棒球場概念示意（非實際座位圖）</text></svg>'''
slide_defs=[('從32年等待到4萬人吶喊','認識臺北大巨蛋',None,field),('一座什麼樣的球場？','場館規模','K01','<div class="big">40,000<small> 席</small></div>'),('漫長的32年','歷史','K02','<div class="timeline"><p><b>1991</b> 室內球場倡議</p><p><b>2006</b> BOT簽約</p><p><b>2015</b> 停工</p><p><b>2020</b> 復工</p></div>'),('四個日期，不要搞混','開幕','K03','<div class="grid"><div class="panel"><b>11/02</b> 使照</div><div class="panel"><b>11/18</b> 預備賽</div><div class="panel"><b>12/02</b> 啟用</div><div class="panel"><b>12/03</b> 正式賽</div></div>'),('第一場國際正式賽','2023 亞錦賽','K04','<div class="big">4 : 0</div><p>中華臺北 vs 韓國 ｜ 16,647 名觀眾</p>'),('從臺北到東京','2024 世界12強','K05','<div class="grid"><div class="panel"><h3>臺北</h3>臺灣區預賽</div><div class="panel"><h3>東京</h3>11/24 冠軍戰 4：0</div></div>'),('球場變成演唱會舞臺','多功能使用','K06','<div class="big">2024.12.05</div>'),('如何融入城市？','交通與都市','K07','<div class="panel">板南線（藍線） → 國父紀念館站 → 依現場指引</div>'),('公共建設不只看規模','BOT與公共治理','K08','<div class="grid"><div class="panel">Build<br>興建</div><div class="panel">Operate<br>營運</div><div class="panel">Transfer<br>移轉</div></div>')]
slides=[]
for i,(title,sub,k,visual) in enumerate(slide_defs):
    e=M[k] if k else None
    slides.append(f'<section class="slide{" active" if i==0 else ""}"><p class="kicker">{i+1:02d} / {sub}</p><h2>{title}</h2>{visual}'+(f'<p>{e["text"]}</p><small>Wiki：<a href="wiki.html#{k}">{k}</a> ｜ {links(e["refs"])}</small>' if e else '<p>從棒球、建築到城市生活，理解一座巨蛋的故事。</p>')+'</section>')
slides.append('''<section class="slide"><p class="kicker">10 / QUIZ</p><h2>你真的認識大巨蛋了嗎？</h2><p>2024 世界12強的冠軍戰在哪裡舉行？</p><div class="quiz"><button data-correct="0">臺北大巨蛋</button><button data-correct="1">東京巨蛋</button><button data-correct="0">天母棒球場</button></div><p id="feedback" aria-live="polite"></p><small>解答來源：<a href="wiki.html#K05">K05</a> · <a href="wiki.html#S07">S07</a></small><div class="panel"><h3>三個關鍵記憶</h3><p>32年歷程、4萬席室內球場、多功能城市場館。</p></div></section>''')
slides.append('<section class="slide"><p class="kicker">11 / SOURCES</p><h2>延伸閱讀與資料來源</h2><p>每張內容頁都能返回 Wiki 知識條目。以下是本次整理使用的10篇資料。</p><div class="grid">'+''.join(f'<div><a href="wiki.html#{s[0]}">{s[0]} · {esc(s[1])}</a></div>' for s in S)+'</div></section>')
js='''let i=0;const all=[...document.querySelectorAll('.slide')];function go(n){i=Math.max(0,Math.min(n,all.length-1));all.forEach((s,j)=>s.classList.toggle('active',i===j));document.querySelector('#page').textContent=(i+1)+' / '+all.length;document.querySelector('progress').value=i+1;document.querySelector('#prev').disabled=i===0;document.querySelector('#next').disabled=i===all.length-1;}document.querySelector('#prev').onclick=()=>go(i-1);document.querySelector('#next').onclick=()=>go(i+1);document.addEventListener('keydown',e=>{if(e.key==='ArrowRight')go(i+1);if(e.key==='ArrowLeft')go(i-1);});document.querySelector('#full').onclick=()=>{if(!document.fullscreenElement)document.documentElement.requestFullscreen?.();else document.exitFullscreen?.()};document.querySelectorAll('[data-correct]').forEach(b=>b.onclick=()=>document.querySelector('#feedback').textContent=b.dataset.correct==='1'?'正確！11月24日於東京巨蛋奪冠。':'再想想：臺北是預賽場地，冠軍戰在日本。');go(0);'''
(P/'slides.html').write_text(page('認識臺北大巨蛋｜教學簡報',''.join(slides)+f'<div class="controls"><button id="prev">← 上一頁</button><span id="page"></span><button id="next">下一頁 →</button><button id="full">全螢幕</button></div><progress value="1" max="{len(slides)}"></progress><small>也可使用鍵盤左右方向鍵翻頁。</small>',js))
# Report references real test results.
rows=''.join(f'<tr><td>{esc(a["query"])}</td><td>{a["expected"]}</td><td>{"通過" if a["passed"] else "漏檢"}</td><td>{"通過" if b["passed"] else "漏檢"}</td></tr>' for a,b in zip(rounds[0]['rows'],rounds[1]['rows']))
report=f'''<p class="kicker">LLM WIKI / ASSIGNMENT</p><h1>臺北大巨蛋：從32年等待到4萬人吶喊</h1><p>主題選擇：從臺灣的棒球與娛樂場館出發，理解大型公共建設的歷史、運作與社會意義。教學對象為沒有相關背景的同學。</p><div class="grid"><div class="panel"><div class="big">10</div>篇資料</div><div class="panel"><div class="big">8</div>個 Wiki 條目</div><div class="panel"><div class="big">11</div>頁簡報</div></div><h2>1 / 先討論、後生成</h2><p>對話中原主題為 RAG，使用者提出改為臺北大巨蛋。依此選擇歷史、場館、運動、娛樂與公共治理五個面向；AI 建議初學者能理解的知識架構，再查找資料、整理成 Wiki。沒有另行假造師生討論。</p><p>範圍以2023–2024啟用與代表事件為主，不承諾截至今日的所有營運資訊。</p><h2>2 / Wiki 成果</h2><p><a href="wiki.html">開啟 Wiki</a> ｜ <a href="wiki.md">Markdown 版本</a> ｜ <a href="knowledge.json">知識資料 JSON</a></p><p>每來源有識別碼、網址、日期與原創摘要；每知識條目有問題、標籤與來源索引。10篇來源見 Wiki 下方。</p><h2>3 / 教學 HTML 簡報</h2><p><a href="slides.html">開啟11頁教學簡報</a>，含室內球場示意、歷史時間線、兩場國際賽區別與互動測驗。</p><h2>4 / Loop / Graph</h2><div class="panel"><pre>選題討論 → 定義教學問題\n       ↓\n逐篇取得來源 → 摘要、記錄來源與日期（重複10篇）\n       ↓\n建立 Wiki → 依教學問題查詢\n                  ↓\n     命中預期條目？ ── 否 → 補標籤／問題欄 → 重新查詢\n                  ↓ 是\n     檢查引用、事件日期／地點\n                  ↓ 不足則回到 Wiki 修正\n     讀取通過檢索的知識條目 → 組裝 HTML\n                  ↓\n     瀏覽器測試 → 失敗則修正 → 輸出成果</pre></div><p>分離資料、檢索及生成可避免不必要的重做。Python 以字串檢索，並使用 Wiki 的正文組裝內容頁；LLM 負責資料閱讀、摘要、規劃與程式設計。並非自動呼叫外部 LLM API 或使用 LangGraph。</p><h2>5 / 實際執行紀錄</h2><p>相同8個關鍵詞：第一輪僅標題命中 {rounds[0]['passed']}/8；第二輪加入問題、標籤、正文後命中 {rounds[1]['passed']}/8。此為自訂測試集，並非獨立檢索基準。</p><table><thead><tr><th>搜尋詞</th><th>預期</th><th>第一輪</th><th>第二輪</th></tr></thead><tbody>{rows}</tbody></table><p>來源索引完整性、啟用日期區分、冠軍賽地點區分均通過程式的文字條件檢查。這些並非自動事實查證；來源內容另經查閱與整理。</p><p><a href="run_log.json">原始檢索紀錄</a> ｜ <a href="browser_test.json">瀏覽器測試紀錄</a> ｜ <a href="workflow.py">可重跑 Python 程式</a></p><h2>6 / 反思</h2><div class="panel"><h3>哪一個節點最常出錯？</h3><p>檢索節點。第一輪有 {8-rounds[0]['passed']} 個問題漏檢，例如「東京巨蛋」不是世界12強的條目標題。</p><h3>檢查往前移到哪裡？</h3><p>移到查詢 Wiki 後、HTML 生成前，檢查預期條目、來源編號、日期和地點是否齊全。</p><h3>有沒有修改 Graph？</h3><p>增加問題與標籤等索引，加入檢索失敗回到 Wiki 的循環。尤其不可把臺灣區預賽與東京冠軍戰混為一談，也不能將使用執照、預備賽、啟用、正式賽事寫成同一天。</p></div><p class="muted">限制：目前是可離線使用的HTML檔案，非公開部署網站；外部來源仍需網路。圖形為示意，不是精確場館圖。反思以實際程式測試為依據，未假稱使用者本人操作。</p>'''
(P/'report.html').write_text(page('臺北大巨蛋｜作業報告',report))
print(json.dumps(log,ensure_ascii=False))
